#include <stdio.h>
int main(void){
    int n=6;
    int adj[6][6]={0}, deg[6]={0};
    int e[][2]={{0,1},{0,2},{1,3},{2,3},{3,4},{2,5}};
    int m=6;
    for(int k=0;k<m;k++){ adj[e[k][0]][e[k][1]]=1; deg[e[k][1]]++; }
    int q[6],head=0,tail=0;
    for(int i=0;i<n;i++) if(deg[i]==0) q[tail++]=i;
    printf("topo: ");
    while(head<tail){
        int u=q[head++]; printf("%d ",u);
        for(int v=0;v<n;v++) if(adj[u][v] && --deg[v]==0) q[tail++]=v;
    }
    printf("\n");
    return 0;
}
